export const FOODS: Food[] = L.map(([id, name, bg, keys, w, svg]) => ({ id, name, bg, keys, w, svg: `<svg viewBox="0 0 48 48" xmlns="http://www.w3.org/2000/svg">${svg}</svg>` }));
const FALLBACK = FOODS.find(f => f.id === "plate")!;
const BY_ID = new Map(FOODS.map(f => [f.id, f] as const));

const words = (s: string) => s.toLowerCase().replace(/&/g, " and ").replace(/[^a-z0-9' -]/g, " ").replace(/\s+/g, " ").trim();
/** Strips a plural so "tacos" finds "taco" and "peaches" finds "peach". */
const stem = (w: string) => w.length > 3 && w.endsWith("ies") ? w.slice(0, -3) + "y" : w.length > 4 && /(ches|shes|xes|oes)$/.test(w) ? w.slice(0, -2) : w.length > 3 && w.endsWith("s") && !w.endsWith("ss") ? w.slice(0, -1) : w;
const has = (hay: string, key: string) => (" " + hay + " ").includes(" " + key + " ");

/** The picture that best fits a dinner's name: a dish beats an ingredient, a longer phrase beats a shorter one. */
export function foodFor(name: string): Food {
  const n = words(name);
  if (!n) return FALLBACK;
  const plain = n.split(" ").map(stem).join(" ");
  let best: Food | null = null, bestScore = 0;
  for (const f of FOODS) {
    if (f.id === "plate") continue;
    for (const k of f.keys) {
      const kk = k.split(" ").map(stem).join(" ");
      if (!has(n, k) && !has(plain, kk)) continue;
      const score = f.w * 100 + k.length + (k.includes(" ") ? 40 : 0);
      if (score > bestScore) { best = f; bestScore = score; }
    }
  }
  return best || FALLBACK;
}
export const foodById = (id: string) => BY_ID.get(id) || FALLBACK;

/** A food picture on a soft round tile. */
export function FoodIcon({ name, size = 56, tile = true, style }: { name: string; size?: number; tile?: boolean; style?: CSSProperties }) {
  const f = foodFor(name);
  return (
    <span className="fico" aria-hidden="true" style={{ width: size, height: size, borderRadius: size * .32, background: tile ? f.bg : "none", ...style }}>
      <span style={{ width: size * .78, height: size * .78, display: "block" }} dangerouslySetInnerHTML={{ __html: f.svg }} />
    </span>
  );
}
